/* From Uiverse.io by Javierrocadev - Tags: card, hover, dark, card animation, twitch */
.__UIV_SCOPE__ .temporary__storage {
/*delete this*/
  width: 350px;
  height: 350px;
  background: #1b1a1a;
  border-radius: 15px;
  display: flex;
  justify-content: center;
  align-items: center;
}

.__UIV_SCOPE__ .card {
  width: 320px;
  height: 300px;
  background: #1b1a1a;
  position: relative;
  color: #e6e6ea;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.__UIV_SCOPE__ .image {
  width: 100%;
  height: 180px;
  position: absolute;
  background-color: rgb(144, 197, 47);
  cursor: pointer;
  transition: all .2s ease;
}

.__UIV_SCOPE__ .image::before {
  content: "LIVE";
  position: absolute;
  top: 7px;
  left: 7px;
  font-weight: 900;
  font-size: .8em;
  background-color: rgb(228, 33, 33);
  border-radius: 5px;
  padding: 3px 5px;
}

.__UIV_SCOPE__ .image::after {
  content: "102.2k viewers";
  position: absolute;
  bottom: 7px;
  left: 7px;
  font-weight: 300;
  font-size: .7em;
  background-color: rgb(59, 53, 53);
  border-radius: 2px;
  padding: 3px 5px;
}

.__UIV_SCOPE__ .image__overlay {
  width: 100%;
  height: 180px;
}

.__UIV_SCOPE__ .image:hover {
  transform: translate(8px, -8px);
  box-shadow: -1px 1px 0px 0px violet,-2px 2px 0px 0px violet,-3px 3px 0px 0px violet,-4px 4px 0px 0px violet,-5px 5px 0px 0px violet,-6px 6px 0px 0px violet,-7px 7px 0px 0px violet,-8px 8px 0px 0px violet;
}

.__UIV_SCOPE__ .avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  cursor: pointer;
  background-image: linear-gradient(to right top, #371f05, #654607, #8b7600, #a4ae00, #a8eb12);
}

.__UIV_SCOPE__ .content {
  display: flex;
  flex-direction: row;
  gap: 10px;
}

.__UIV_SCOPE__ .content__text {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.__UIV_SCOPE__ .content__body {
  display: flex;
  flex-direction: column;
}

.__UIV_SCOPE__ .stream__title {
  font-weight: 900;
  width: 260px;
  white-space: nowrap;
  text-overflow: ellipsis;
  overflow: hidden;
  cursor: pointer;
}

.__UIV_SCOPE__ .event {
  cursor: pointer;
}

.__UIV_SCOPE__ .streamer__name, .__UIV_SCOPE__ .event {
  font-size: .8em;
  font-weight: 400;
  color: rgb(216, 213, 213);
}

.__UIV_SCOPE__ .categories__btn {
  text-decoration: none;
  color: rgb(216, 213, 213);
  font-size: .8em;
  background-color: rgb(73, 71, 71);
  padding: 3px 10px;
  border-radius: 15px;
}

.__UIV_SCOPE__ .stream__title:hover, .__UIV_SCOPE__ .event:hover {
  color: #9f7cd3;
}

.__UIV_SCOPE__ .categories__btn:hover {
  background-color: rgb(79, 79, 79);
}
